import sympy
from sympy import factorint, lcm
from functools import reduce
from sympy.abc import x, y, z

# Top-level setup
# We assume the witness is provided as ideals in the ring of integers Z, 
# which is a commutative ring with identity. Ideals in Z are generated by a single integer.
# A witness is expected to be a tuple: (I, [Q_1, Q_2, ..., Q_n]) or (R, I, [Q_1, ..., Q_n])

CONDITION_LABELS = [
    "H_1: R is a commutative ring with identity",
    "H_2: I = ∩_{i=1}^n Q_i is a primary decomposition of I",
    "¬Q: The radical √I is not equal to the intersection of the prime ideals √Q_i"
]

N_HYP = 2
NEG_Q_INDEX = 2

def conditions(witness):
    try:
        # Parse witness
        if isinstance(witness, tuple):
            if len(witness) == 3:
                R, I, Q_list = witness
            elif len(witness) == 2:
                I, Q_list = witness
            else:
                return [False, False, False]
        else:
            return [False, False, False]
            
        # Validate types (expecting integers representing generators of ideals in Z)
        if not isinstance(I, (int, sympy.Integer)):
            return [False, False, False]
            
        if not isinstance(Q_list, (list, tuple)):
            return [False, False, False]
            
        for q in Q_list:
            if not isinstance(q, (int, sympy.Integer)):
                return [False, False, False]
                
        # H_1: R is a commutative ring with identity
        # The ring of integers Z is a commutative ring with identity.
        h1_ok = True
        
        # H_2: I = ∩ Q_i is a primary decomposition of I
        # In Z, an ideal (q) is primary if q = 0 or q = p^k for some prime p and k >= 1.
        # The ideal (1) is the whole ring and is not considered primary.
        all_primary = True
        for q in Q_list:
            q_abs = abs(int(q))
            if q_abs == 0:
                pass  # (0) is a prime ideal, hence primary
            elif q_abs == 1:
                all_primary = False
                break
            else:
                factors = factorint(q_abs)
                if len(factors) != 1:
                    all_primary = False
                    break
                    
        # Intersection of ideals in Z corresponds to the least common multiple (LCM)
        if not Q_list:
            lcm_Q = 1
        else:
            lcm_Q = reduce(lcm, [abs(int(q)) for q in Q_list])
            
        h2_ok = all_primary and (abs(int(I)) == lcm_Q)
        
        # Conclusion: √I = ∩ √Q_i
        # The radical of an ideal (q) in Z is generated by the product of its distinct prime factors.
        def radical(q):
            q_abs = abs(int(q))
            if q_abs == 0:
                return 0
            if q_abs == 1:
                return 1
            factors = factorint(q_abs)
            rad = 1
            for p in factors:
                rad *= p
            return rad
            
        rad_I = radical(I)
        
        if not Q_list:
            lcm_rad_Q = 1
        else:
            lcm_rad_Q = reduce(lcm, [radical(q) for q in Q_list])
            
        q_holds = (abs(rad_I) == abs(lcm_rad_Q))
        neg_q_ok = not q_holds
        
        return [h1_ok, h2_ok, neg_q_ok]
        
    except Exception:
        return [False, False, False]